-- shipping-service schema (fixture for test data from the database: dictionaries, checks, FKs)
drop schema if exists ship cascade;
create schema ship;
create table ship.d_carriers (code varchar(10) primary key, name text not null, max_weight_kg numeric(8,3), active boolean not null default true);
insert into ship.d_carriers values ('OLD', 'Retired post', 10, false), ('DHL', 'DHL Parcel', 31.5, true), ('UPS', 'UPS Standard', 70, true);
create table ship.d_countries (code char(2) primary key, name text not null);
insert into ship.d_countries values ('DE', 'Germany'), ('FR', 'France'), ('NL', 'Netherlands');
create table ship.d_parcel_types (id bigint primary key, code varchar(20) not null unique, name text not null, active boolean not null default true);
insert into ship.d_parcel_types values (1, 'BOX', 'Box', true), (2, 'ENVELOPE', 'Envelope', true), (3, 'PALLET', 'Pallet', false);
create table ship.d_service_levels (code text primary key, name text not null);
insert into ship.d_service_levels values ('STANDARD', 'Standard'), ('EXPRESS', 'Express'), ('SAME_DAY', 'Same day'), ('ECONOMY', 'Economy');
create table ship.shipments (
  id bigint generated by default as identity primary key,
  order_id bigint not null unique,
  carrier_code varchar(10) not null references ship.d_carriers(code),
  weight_kg numeric(10,3) not null check (weight_kg > 0),
  country char(2) not null references ship.d_countries(code),
  level text not null default 'STANDARD' references ship.d_service_levels(code),
  status text not null default 'CREATED' check (status in ('CREATED', 'SENT', 'DELIVERED', 'RETURNED')),
  tracking_no varchar(40),
  created_at timestamptz not null default now()
);
create table ship.shipment_events (id bigserial primary key, shipment_id bigint not null references ship.shipments(id), status text not null, at timestamptz not null default now());
create function ship.shipped_weight(p_country char(2)) returns numeric language sql stable as $$
  select coalesce(sum(weight_kg), 0) from ship.shipments where country = p_country and status in ('SENT', 'DELIVERED')
$$;
